package com.echovault.servlet;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;@WebServlet("/admin-logout") public class AdminLogoutServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException{HttpSession h=q.getSession(false);if(h!=null){h.removeAttribute("adminId");h.removeAttribute("adminName");}s.sendRedirect("admin-login.jsp");}}